// Created: 2026-10-31

/**
 * Dispatch proof: evidence that each handler folded into a tool dispatcher
 * still runs (yellow-refactor M1). A lower process count also passes if the
 * folded handlers silently do nothing, so the dispatchers can report, per
 * handler, that they called it and whether it returned or threw.
 *
 *   ORK_DISPATCH_PROOF=1          append one token per handler run to the
 *                                 result's systemMessage:
 *                                 ork-proof:<event>:<tool>:<id>@ok|failed
 *   ORK_DISPATCH_PROOF_BREAK=<id> in proof mode only, replace that handler
 *                                 with one that throws, so a broken handler
 *                                 must show as failed
 *
 * Off by default; a measurement switch, not a feature. The tokens are counted
 * in a live `claude --debug-file` log by scripts/check-dispatch-proof.mjs.
 */

export const PROOF_PREFIX = 'ork-proof:';

export type ProofEnv = Readonly<Record<string, string | undefined>>;

export interface ProofToken {
  event: string;
  tool: string;
  id: string;
  outcome: 'ok' | 'failed';
}

export function proofEnabled(env: ProofEnv): boolean {
  return env.ORK_DISPATCH_PROOF === '1';
}

/** True when proof mode is on and `id` is the handler to break. */
export function proofBreaks(env: ProofEnv, id: string): boolean {
  return proofEnabled(env) && env.ORK_DISPATCH_PROOF_BREAK === id;
}

/** The throw a broken handler raises. */
export function proofBreakError(id: string): Error {
  return new Error(`ORK_DISPATCH_PROOF_BREAK broke ${id} on purpose`);
}

export function proofToken(t: ProofToken): string {
  return `${PROOF_PREFIX}${t.event}:${t.tool}:${t.id}@${t.outcome}`;
}

/** Collects tokens for one dispatcher run; a no-op when proof mode is off. */
export class ProofLog {
  private readonly tokens: ProofToken[] = [];

  constructor(
    private readonly env: ProofEnv,
    private readonly event: string,
    private readonly tool: string,
  ) {}

  record(id: string, outcome: 'ok' | 'failed'): void {
    if (proofEnabled(this.env)) this.tokens.push({ event: this.event, tool: this.tool, id, outcome });
  }

  /** systemMessage with the tokens appended (unchanged when proof mode is off). */
  appendTo(systemMessage: string | undefined): string | undefined {
    if (!proofEnabled(this.env) || this.tokens.length === 0) return systemMessage;
    const line = this.tokens.map(proofToken).join(' ');
    return systemMessage ? `${systemMessage}\n${line}` : line;
  }
}

const TOKEN_RE = /ork-proof:([A-Za-z]+):([^:\s]+):(\S+?)@(ok|failed)/g;

/** Parse every proof token out of a text. */
export function proofTokens(text: string): ProofToken[] {
  const out: ProofToken[] = [];
  for (const m of text.matchAll(TOKEN_RE)) {
    out.push({ event: m[1], tool: m[2], id: m[3], outcome: m[4] as 'ok' | 'failed' });
  }
  return out;
}
